def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > 60:
                    strong_prev.append(float(bid))

    if not alive:
        return max(0.0, min(float(budget), 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_prev = sorted_bids[int(1)]

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 0.8
    elif no_water == 1:
        urgency += 0.35
    if day >= 8:
        urgency += 0.15
    urgency += 0.35 * scarcity

    if hp <= 2 or no_water >= 2:
        target = max(88.0, highest_prev + 2.5)
    elif urgency >= 1.0:
        target = max(72.0, second_prev + 1.5, highest_prev * 0.9)
    elif scarcity >= 0.7:
        target = max(58.0, second_prev + 1.0)
    elif scarcity <= 0.25 and hp >= 5 and no_water == 0:
        target = 16.0
    else:
        if highest_prev >= 110:
            target = 24.0 if hp >= 5 else 68.0
        elif highest_prev >= 90:
            target = 30.0 if hp >= 5 else 74.0
        elif highest_prev >= 70:
            target = max(34.0, second_prev * 0.85)
        else:
            target = 28.0 + 18.0 * scarcity

    if budget < DAILY_SALARY:
        target *= 0.9
    if budget < 40:
        target = min(target, budget)

    floor_bid = 8.0 if hp > 4 and no_water == 0 else 18.0
    bid = max(floor_bid, target)
    bid = min(float(budget), bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        # If no opponents, bid just enough to ensure allocation.
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Estimate how competitive the market was.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine target bid level.
    # Observed: Alex avg ~92 with survival; Cindy bid avg ~96 and still risky; so ~92 is a good anchor.
    anchor = DAILY_SALARY * 1.02  # 91.8

    # If my HP is low or I already had no-water days, I must secure water.
    if my_hp <= 2.5 or my_no_water_days >= 1:
        target = anchor * 1.03  # ~94.5
    else:
        # If opponents previously bid very high, slightly increase; otherwise stay near anchor but not max.
        if highest_prev_bid >= anchor * 1.05:
            target = anchor * 1.08
        elif highest_prev_bid >= anchor * 0.95:
            target = anchor * 0.98
        else:
            target = anchor * 0.90

    # Convert target into an actual bid constrained by budget.
    bid = max(0.0, min(my_budget, target))

    # Additional safeguard: if supply is low, competition likely higher; nudge up.
    if supply <= float(MIN_SUPPLY) + 0.5:
        bid = max(bid, min(my_budget, anchor * 1.05))

    # Final cap: never bid above budget.
    if bid > my_budget:
        bid = my_budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
